<script setup>
import PagedRecords from './PagedRecords.vue';
import {computed,ref} from 'vue';import {number,percent,s} from './store';
const props=defineProps({rows:{type:Array,default:()=>[]},title:String,pie:Boolean,trend:Boolean,source:Boolean,table:Boolean,mobile:Boolean,compact:Boolean});
const chartWidth=ref(300);
const columns=[{key:'label',label:'Nhóm'},{key:'count',label:'Đăng ký',align:'right'},{key:'percent',label:'Tỷ lệ',align:'right'}];
// Distinct hues from the MDS categorical palette, shared with the HTML legend.
const colors=['--mds-chart-blue-1','--mds-chart-green-1','--mds-chart-blue-6','--mds-chart-purple-1','--mds-chart-cyan-1','--mds-chart-ros-1','--mds-chart-blue-gray-1'];
const color=i=>`var(${colors[i%colors.length]})`;
const visibleRows=computed(()=>props.trend?props.rows:props.rows.slice(0,20));
const chartHeight=computed(()=>props.mobile?(props.pie?224:props.trend?248:Math.min(300,Math.max(220,visibleRows.value.length*34+44))):props.compact?300:props.trend?340:Math.max(300,props.pie?340:Math.min(visibleRows.value.length*38+50,650)));
const pieRadius=computed(()=>props.mobile?Math.min(92,chartWidth.value/2-20):Math.max(40,Math.min(134,chartWidth.value/2-56)));
const pieLabels=computed(()=>s.showPercent&&!props.mobile);
const chart=computed(()=>{
 const rows=visibleRows.value;
 const common={legend:{show:false},tooltip:{renderMode:'richText',confine:true,trigger:'item',formatter:p=>`${p.name}: ${number(p.value)} (${percent(rows[p.dataIndex]?.percent)})`},aria:{enabled:true},animation:false};
 if(props.pie)return {...common,color:rows.map((_,i)=>color(i)),series:[{type:'pie',radius:[pieRadius.value*.62,pieRadius.value],center:['50%','50%'],data:rows.map(r=>({name:r.label,value:r.count})),label:{show:pieLabels.value,position:'outside',alignTo:'none',bleedMargin:4,distanceToLabelLine:2,formatter:p=>percent(rows[p.dataIndex]?.percent),color:'var(--mds-text-secondary)',fontSize:12},labelLine:{show:pieLabels.value,length:6,length2:4},labelLayout:{hideOverlap:true,moveOverlap:'shiftY'}}]};
 if(props.trend)return {...common,tooltip:{...common.tooltip,trigger:'axis',formatter:items=>{const p=items[0];return `${p.name}\n${number(rows[p.dataIndex]?.count)} khách đăng ký`; }},grid:{left:8,right:20,top:32,bottom:rows.length>14?72:24,containLabel:true},xAxis:{type:'category',data:rows.map(r=>r.label),axisLabel:{hideOverlap:true,rotate:0,formatter:value=>props.mobile?value.slice(0,5):value}},yAxis:{type:'value',min:0,minInterval:1,axisLabel:{formatter:number}},dataZoom:rows.length>14?[{type:'slider',bottom:8,startValue:Math.max(0,rows.length-14),endValue:rows.length-1}]:[],series:[{name:'Khách đăng ký',type:'bar',barMaxWidth:40,itemStyle:{color:'var(--mds-brand)'},data:rows.map(r=>r.count),label:{show:true,position:'inside',color:'var(--mds-base-white)',formatter:p=>p.value?number(p.value):''}},{name:'Xu hướng',type:'line',smooth:false,symbol:'circle',symbolSize:7,itemStyle:{color:'var(--mds-chart-blue-6)'},lineStyle:{width:3,color:'var(--mds-chart-blue-6)'},data:rows.map(r=>r.count),z:3}]};
 const showPct=props.source||s.showPercent;
 const bars={type:'bar',barMaxWidth:28,data:rows.map(r=>r.count),itemStyle:{color:'var(--mds-brand)'},label:{show:props.source||s.showPercent,position:props.source?'inside':'right',color:props.source?'var(--mds-base-white)':'var(--mds-text)',formatter:p=>props.source?(p.value?number(p.value):''):percent(rows[p.dataIndex]?.percent)},labelLayout:{hideOverlap:true}};
 return {...common,dataZoom:props.compact&&props.source&&rows.length>8?[{type:'slider',yAxisIndex:0,orient:'vertical',right:0,width:10,startValue:0,endValue:7,showDetail:false}]:[],grid:{left:8,right:showPct?72:16,top:16,bottom:16,containLabel:true},xAxis:{type:'value',min:0,minInterval:1,axisLabel:{hideOverlap:true,formatter:number}},yAxis:{type:'category',inverse:true,data:rows.map(r=>r.label),axisLabel:{hideOverlap:true,width:props.mobile?92:160,overflow:props.mobile&&!props.source?'break':'truncate',lineHeight:16}},series:props.source?[bars,{...bars,barGap:'-100%',silent:true,tooltip:{show:false},itemStyle:{color:'transparent'},label:{show:true,position:'right',color:'var(--mds-text)',formatter:p=>percent(rows[p.dataIndex]?.percent)}}]:[bars]};
});
</script>
<template><section class="card chart-wrap"><div class="chart-heading"><h3>{{title}}</h3><slot name="controls"/></div><MEmptyState v-if="!rows.length" type="no-result" title="Không có dữ liệu phù hợp"/><template v-else>
<div v-if="!table" :class="{'donut-layout':pie,'donut-mobile':pie&&mobile}"><div class="chart-canvas"><MChart @resize="chartWidth=$event.width" :option="chart" :height="chartHeight" :aria-label="title"/><div v-if="pie&&mobile" class="donut-total"><strong>{{number(rows.reduce((sum,r)=>sum+r.count,0))}}</strong><span>đăng ký</span></div></div><ul v-if="pie" class="chart-legend" aria-label="Chú giải cơ cấu chức vụ"><li v-for="(r,i) in visibleRows" :key="r.label"><span class="legend-dot" :style="{background:color(i)}"/><span class="legend-detail"><span class="legend-name">{{r.label}}</span><span class="legend-value">{{number(r.count)}} · {{percent(r.percent)}}</span></span></li></ul></div>
<PagedRecords v-else :rows="rows" :all="s.exportingImage" v-slot="{rows:pageRows}"><div v-if="mobile" class="mobile-list"><article v-for="r in pageRows" :key="r.label" class="row justify-between"><span>{{r.label}}</span><strong>{{number(r.count)}} · {{percent(r.percent)}}</strong></article></div><div v-else class="report-table"><MDataTable :columns="columns" :rows="pageRows" :pagination="false" row-key="label"><template #cell-count="{row}">{{number(row.count)}}</template><template #cell-percent="{row}">{{percent(row.percent)}}</template></MDataTable></div></PagedRecords>
<p v-if="!table&&trend&&!mobile" class="muted">Cột: số khách đăng ký từng ngày · Đường: xu hướng tăng giảm theo cùng số khách.</p><p v-if="!table&&!trend&&rows.length>20" class="muted">Hiển thị 20 nhóm đầu. Xem đầy đủ trong bảng số liệu.</p>
</template></section></template>
